### What steps will reproduce the bug?

Save the following code into a file and run it. The second GET request reports a stream error (`ERR_HTTP2_STREAM_ERROR: Stream closed with error code NGHTTP2_ENHANCE_YOUR_CALM`) rather than responding with a 200.

```js
// Cancel a queued upload, then reuse the session: node cancel-queued-body.mjs
import assert from 'node:assert/strict';
import { once } from 'node:events';
import http2 from 'node:http2';

const { NGHTTP2_CANCEL } = http2.constants;
// Keep the upload queued on the client until the server cancels it.
const server = http2.createServer({ settings: { initialWindowSize: 0 } });
const sessions = new Set();
server.on('session', (session) => sessions.add(session));
server.on('stream', (stream, headers) => {
  if (headers[':method'] === 'POST') {
    stream.close(NGHTTP2_CANCEL);
    return;
  }
  stream.respond({ ':status': 200 });
  stream.end();
});

// A timeout reports a hang; it does not control the reproduction's timing.
const timeout = setTimeout(() => {
  console.error('TIMEOUT');
  process.exit(1);
}, 5000);
let client;
try {
  server.listen(0, '127.0.0.1');
  await once(server, 'listening');
  client = http2.connect(`http://127.0.0.1:${server.address().port}`, {
    maxSessionMemory: 1,
  });
  // Wait until the client knows it cannot send any upload bytes.
  await once(client, 'remoteSettings');
  const get = () => new Promise((resolve) => {
    const req = client.request({ ':method': 'GET' }, { endStream: true });
    req.on('response', (headers) => resolve(`status ${headers[':status']}`));
    req.on('error', (err) => resolve(`${err.code}: ${err.message}`));
    req.resume();
  });

  console.log(`node ${process.version}`);
  const before = await get();
  console.log('small request before cancellation:', before);
  assert.equal(before, 'status 200');

  const upload = client.request({ ':method': 'POST' });
  upload.on('error', (err) => {
    assert.equal(err.code, 'ERR_HTTP2_STREAM_ABORTED');
  });
  const closed = new Promise((resolve) => upload.once('close', resolve));
  upload.write(Buffer.alloc(4 * 1024 * 1024));
  await closed;
  assert.equal(upload.rstCode, NGHTTP2_CANCEL);
  console.log('4 MiB queued upload: canceled by server (expected)');

  const after = await get();
  console.log('small request after cancellation: ', after);
  if (after !== 'status 200') process.exitCode = 1;
} finally {
  clearTimeout(timeout);
  client?.destroy();
  for (const session of sessions) session.destroy();
  server.close();
}
```

